effect.shader:
// Ring Distortion Fade

void main(){
  vec2 res = acScreenSize;
  vec2 uv = acScreenNorm; // 0..1

  // Time 0..1
  float pr = autoTime ? mod(acTime, duration) / max(0.0001, duration) : clamp(progress, 0.0, 1.0);

  // Convert offset from chosen center to pixel-normalized space (preserving circularity)
  vec2 center = vec2(centerX, centerY);
  float minDim = min(res.x, res.y);
  vec2 offsetFromCenter = (uv - center) * res / max(1.0, minDim);

  // Direction toward center; if zero length, no offset
  float lenO = length(offsetFromCenter);
  vec2 offsetDir = lenO > 1e-6 ? normalize(-offsetFromCenter) : vec2(0.0);

  // Band logic
  float halfWidth = effectWidth * 0.5;
  float lower = 1.0 - smoothstep(pr - halfWidth, pr, lenO);
  float upper = smoothstep(pr, pr + halfWidth, lenO);
  float band = 1.0 - (upper + lower);

  float strength = 1.0 - pr; // fades out over time
  float fadeStrength = smoothstep(0.0, fadeInTimeFactor, pr); // fades in initially
  float distortion = band * strength * fadeStrength;

  // Apply offset in texels, clamp sampling inside valid area
  vec2 texelSize = 1.0 / getTexSize(inputImg.size);
  vec2 uvOff = uv + texelSize * (offsetDir * maxTexelOffset * distortion);
  vec2 halfTex = texelSize * 0.5;
  uvOff = clamp(uvOff, halfTex, 1.0 - halfTex);

  vec4 col = texture2DCv(inputImg.texture, uvOff);
  gl_FragColor = col;
}
